SELECT CASE WHEN quantity >= 194 THEN 'high' WHEN quantity >= 105 THEN 'mid' ELSE 'low' END AS quantity_bucket, SUM(quantity) AS total_quantity, SUM(SUM(quantity)) OVER (ORDER BY CASE WHEN quantity >= 194 THEN 'high' WHEN quantity >= 105 THEN 'mid' ELSE 'low' END) AS cumulative_quantity FROM inventory WHERE product_id IN (3, 9) GROUP BY CASE WHEN quantity >= 194 THEN 'high' WHEN quantity >= 105 THEN 'mid' ELSE 'low' END;
